control_sql:
SELECT customer_id, COUNT(alert_id) FILTER (WHERE status = 'open') AS open_alerts
FROM alerts
GROUP BY customer_id;

treatment_sql:
SELECT investigation_id, EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600.0 AS resolution_hours
FROM investigations
WHERE closed_at IS NOT NULL;

